/** Defines a scorer-first legacy eval suite. Prefer root `describeEval(...)`. */
declare function describeEval(name: string, options: LegacyDescribeEvalOptions): void;

export { type LegacyDescribeEvalOptions, ScoreFn, TaskFn, type ToEval, describeEval };
